.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Later</text><text x=\"28\" y=\"78\">Event 3, even if silent</text><text x=\"358\" y=\"42\">Last</text><text x=\"358\" y=\"78\">Event 4 closes the story</text></g></svg>"}],"year_level":"Year 7"}') WHERE seed_key='s5-music-y9-w04-l2' AND family_id IS NULL;
